const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d');let assets=[],clips=[],selected=-1,playhead=0,playing=false,loading=false,activeId=null,history=[],audioCtx,destination,musicNode,musicGain,recorder,exporting=false,cancelled=false,sceneCuts=[],quietRanges=[],analysisBusy=false;const music=new Audio();music.volume=.4;let musicFile=null,raf=0;
