let zone=$('dropzone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.style.borderColor='#d6b8ff'});zone.addEventListener('dragleave',()=>zone.style.borderColor='');zone.addEventListener('drop',e=>{e.preventDefault();zone.style.borderColor='';importFiles(e.dataTransfer.files)});
