function shapeExtraFields(t){let editing=shapeEdit?.id===t.id,pts=validPoints(t),k=pts?[...new Set(t.points.map(q=>q[2]?1:0))]:[];return `<label>Width %<input type="number" min="5" max="2000" step="1" value="${Math.round((t.sx||1)*100)}" onchange="editGraphic('${t.id}','sx',+this.value/100)"></label><label>Height %<input type="number" min="5" max="2000" step="1" value="${Math.round((t.sy||1)*100)}" onchange="editGraphic('${t.id}','sy',+this.value/100)"></label><label>Points<button class="graphic-toggle" aria-pressed="${editing}" onclick="${editing?'endShapeEdit()':`startShapeEdit('${t.id}')`}">${editing?'✓ Done':'✎ Edit points'}</button></label><label>Draw<button class="graphic-toggle" onclick="startShapeDraw('${t.id}')">✏ Draw outline</button></label>${pts?`<label>Corners<select onchange="setShapeCorners('${t.id}',this.value)"><option value="0" ${k.length===1&&!k[0]?'selected':''}>Sharp</option><option value="1" ${k.length===1&&k[0]?'selected':''}>Smooth</option>${k.length>1?'<option value="mixed" selected disabled>Mixed</option>':''}</select></label><label>Outline<button class="graphic-toggle" onclick="resetShapePoints('${t.id}')">↺ Reset shape</button></label>`:''}`}
const shapeBaseEditGraphic=editGraphic;editGraphic=function(id,key,value,refresh=true){let t=graphicTracks.find(t=>t.id===id);if(t?.type==='shape'){if(key==='sx'||key==='sy'){if(!Number.isFinite(value)||value<=0){toast('Choose a valid value.');renderGraphicTracks();return}value=Math.min(20,Math.max(.05,value))}if(key==='shape'&&!exporting){if(shapeEdit?.id===id)shapeEdit=null;if(value==='custom'){startShapeDraw(id);return}t.points=null}}return shapeBaseEditGraphic(id,key,value,refresh)};
function setShapeCorners(id,v){let t=graphicTracks.find(t=>t.id===id);if(!t||!validPoints(t)||v==='mixed')return;t.points=t.points.map(q=>[q[0],q[1],+v]);renderGraphicTracks()}
function resetShapePoints(id){let t=graphicTracks.find(t=>t.id===id);if(!t)return;if(t.shape==='custom'){startShapeDraw(id);return}t.points=null;if(shapeEdit?.id===id)shapeEdit=null;renderGraphicTracks();toast('Back to the original '+shapeLabel(t.shape).toLowerCase()+'.')}
function seekIntoTrack(t){if(playhead<t.offset||playhead>=t.offset+t.length)seekTimeline(t.offset+Math.min(.5,t.length/2))}
function startShapeEdit(id){let t=graphicTracks.find(t=>t.id===id);if(!t||exporting||!shapeReady(t))return;pause();if(!validPoints(t))t.points=presetPoints(t.shape);shapeDraw=null;shapeEdit={id,drag:-1};selectedTextId=null;seekIntoTrack(t);renderGraphicTracks();toast('Drag points to reshape · double-click an edge to add a point, a point to remove it · Enter when done')}
