function startShapeDraw(id,isNew=false){let t=graphicTracks.find(t=>t.id===id);if(!t||exporting)return;pause();shapeEdit=null;shapeDraw={id,pts:[],down:false,sketched:false,hover:null,isNew,prev:{shape:t.shape,points:t.points?structuredClone(t.points):null}};selectedTextId=null;seekIntoTrack(t);renderGraphicTracks();toast('Click to place points or drag to sketch · click the first point or press Enter to finish · Esc cancels')}
function cancelShapeDraw(){if(!shapeDraw)return;let d=shapeDraw,t=graphicTracks.find(t=>t.id===d.id);shapeDraw=null;if(t&&d.isNew)graphicTracks=graphicTracks.filter(x=>x!==t);else if(t)Object.assign(t,d.prev);renderGraphicTracks()}
function finishShapeDraw(){if(!shapeDraw)return;let d=shapeDraw,t=graphicTracks.find(t=>t.id===d.id),P=d.pts;if(!t){shapeDraw=null;return}let xs=P.map(q=>q.x),ys=P.map(q=>q.y),x0=Math.min(...xs),x1=Math.max(...xs),y0=Math.min(...ys),y1=Math.max(...ys),W=x1-x0,H=y1-y0,min=handleRadius()*2;if(P.length<3||W<min||H<min){toast('Place at least three points to make a shape.');return}let w=canvas.width,cx=(x0+x1)/2,cy=(y0+y1)/2,size=Math.round(Math.min(240,Math.max(12,H/(2*w/1280)))),base=size*w/1280*2;Object.assign(t,{shape:'custom',x:cx/w*100,y:cy/canvas.height*100,size,sx:W/base,sy:H/base,rotation:0,flipH:false,flipV:false,points:P.map(q=>[(q.x-cx)/W,(q.y-cy)/H,d.sketched?1:0])});shapeDraw=null;selectedTextId=t.id;renderGraphicTracks();toast('Shape drawn. Use ✎ Edit points to fine-tune it.')}
