function endShapePointer(e){if(shapeDraw?.down){e?.stopImmediatePropagation();let d=shapeDraw;d.down=false;if(d.sketched&&d.pts.length>=3)finishShapeDraw();return}if(shapeEdit&&shapeEdit.drag!==-1){e?.stopImmediatePropagation();shapeEdit.drag=-1;canvas.style.cursor='default';renderGraphicTracks()}}
