const drawWithShapeTools=draw;draw=function(){drawWithShapeTools();if(exporting)return;let r=handleRadius(),lw=2*canvas.width/Math.max(1,canvas.getBoundingClientRect().width);
if(shapeEdit){let t=graphicTracks.find(t=>t.id===shapeEdit.id);if(t&&validPoints(t)&&visibleText(t)){ctx.save();ctx.lineWidth=lw;ctx.strokeStyle='#cfacff';ctx.setLineDash([lw*3,lw*3]);ctx.beginPath();t.points.forEach((q,i)=>{let c=toCanvas(t,q[0],q[1]);i?ctx.lineTo(c.x,c.y):ctx.moveTo(c.x,c.y)});ctx.closePath();ctx.stroke();ctx.setLineDash([]);t.points.forEach((q,i)=>{let c=toCanvas(t,q[0],q[1]);ctx.beginPath();if(q[2])ctx.arc(c.x,c.y,r*.75,0,Math.PI*2);else ctx.rect(c.x-r*.65,c.y-r*.65,r*1.3,r*1.3);ctx.fillStyle=i===shapeEdit.drag?'#cfacff':'#fff';ctx.fill();ctx.stroke()});ctx.restore()}}
if(shapeDraw&&shapeDraw.pts.length){let P=shapeDraw.pts,h=shapeDraw.hover;ctx.save();ctx.lineWidth=lw;ctx.strokeStyle='#cfacff';ctx.fillStyle='#cfacff33';ctx.beginPath();P.forEach((q,i)=>i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y));if(h&&!shapeDraw.down)ctx.lineTo(h.x,h.y);if(P.length>=3)ctx.fill();ctx.stroke();P.forEach((q,i)=>{ctx.beginPath();ctx.arc(q.x,q.y,i===0&&P.length>=3?r*1.1:r*.55,0,Math.PI*2);ctx.fillStyle=i===0?'#cfacff':'#fff';ctx.fill();ctx.stroke()});ctx.restore()}};
